import React from 'react';
import './style.css';

const translations = {
  'pt-BR': {
    title: 'Experiência',
    experiences: [
      {
        company: 'Esteio em Vicosa',
        position: 'Estagiária em Desenvolvimento Mobile',
        type: 'Estágio',
        date: 'Janeiro 2023 - Maio 2023',
        location: 'Vicosa, Minas Gerais, Brasil',
        description: 'Desenvolvimento focado em aplicativos móveis com React Native (Expo) para iOS e Android, integrados com backend Laravel. Participação nas fases de análise, desenvolvimento, homologação e testes de soluções agrícolas móveis.'
      },
      {
        company: 'EmComp - Empresa Júnior da Computação',
        position: 'Desenvolvedora Full-Stack',
        type: 'Tempo Integral',
        date: 'Maio de 2023 - Presente',
        location: 'Rio Pomba, Minas Gerais, Brasil',
        description: 'Trabalho voluntário como desenvolvedora <strong>Full-Stack</strong> na <strong>EmComp</strong>, participando de projetos de desenvolvimento de software e soluções tecnológicas para clientes e parceiros da empresa júnior.'
      }
    ]
  },
  en: {
    title: 'Experience',
    experiences: [
      {
        company: 'Esteio em Vicosa',
        position: 'Mobile Development Intern',
        type: 'Internship',
        date: 'January 2023 - May 2023',
        location: 'Vicosa, Minas Gerais, Brazil',
        description: 'Focused development of mobile applications with React Native (Expo) for iOS and Android, integrated with Laravel backend. Participation in analysis, development, validation and testing phases of agricultural mobile solutions.'
      },
      {
        company: 'EmComp - Computer Science Junior Company',
        position: 'Full-Stack Developer',
        type: 'Full-Time',
        date: 'May 2023 - Present',
        location: 'Rio Pomba, Minas Gerais, Brazil',
        description: 'Volunteer work as a <strong>Full-Stack</strong> developer at <strong>EmComp</strong>, participating in software development projects and technological solutions for the junior company\'s clients and partners.'
      }
    ]
  }
};

const Experience = ({ language }) => {
  const translation = translations[language];

  return (
    <div className="experience-container">
      <h2>{translation.title}</h2>

      {translation.experiences.map((exp, index) => (
        <section 
          key={`${index}-${exp.company}`} 
          className={`experience-section ${index === 0 ? 'first-experience' : ''}`}
        >
          <ul>
            <li>
              <h3>{exp.company}</h3>
              <p className="position">{exp.position}</p>
              <p>{exp.type}</p>
              <p>{exp.date}</p>
              <p>{exp.location}</p>
              <p dangerouslySetInnerHTML={{ __html: exp.description }} />
            </li>
          </ul>
        </section>
      ))}
    </div>
  );
}

export default Experience;
